 "use client";
 import { useMemo, useState } from "react";

 type Item = { id?: string; sku:string; description:string; quantity:number; unitPricePaise:number; lineTotalPaise:number };
 type Props = {
   id:string;
   poNumber:string;
   poDate:string;
   vendorName:string;
   documentTotalPaise:number;
   extractionMethod:string;
   status:string;
   lineItems:Item[];
   editable:boolean;
   approverCanDecide:boolean;
 };

 export default function PoReview(props:Props) {
   const [header, setHeader] = useState({ poNumber:props.poNumber, poDate:props.poDate, vendorName:props.vendorName, documentTotal:(props.documentTotalPaise/100).toFixed(2) });
   const [items, setItems] = useState(props.lineItems.map(item => ({
     sku:item.sku,
     description:item.description,
     quantity:item.quantity,
     unitPrice:(item.unitPricePaise/100).toFixed(2),
     lineTotal:(item.lineTotalPaise/100).toFixed(2)
   })));
   const [error,setError] = useState("");
   const [reason,setReason] = useState("");

   const calculated = useMemo(() => items.reduce((sum,item) => sum + Math.round(Number(item.lineTotal||0)*100),0),[items]);
   const documentTotal = Math.round(Number(header.documentTotal||0)*100);
   const poMismatch = items.length > 0 && Math.abs(calculated-documentTotal)>100;

   function updateItem(index:number,key:string,value:string|number) {
     setItems(items.map((item,i) => i===index ? {...item,[key]:value} : item));
   }
   async function save() {
     setError("");
     const response=await fetch(`/api/pos/${props.id}`,{
       method:"PATCH", headers:{"Content-Type":"application/json"},
       body:JSON.stringify({...header,lineItems:items})
     });
     const data=await response.json();
     if(!response.ok) setError(data.error||"Could not save");
   }
   async function action(action:"submit"|"approve"|"reject") {
     setError("");
     const url = action==="submit" ? `/api/pos/${props.id}/submit` : `/api/pos/${props.id}/decision`;
     const response=await fetch(url,{
       method:"POST", headers:{"Content-Type":"application/json"},
       body:JSON.stringify(action==="submit"?{}:{action:action==="approve"?"APPROVE":"REJECT",reason})
     });
     const data=await response.json();
     if(!response.ok) setError(data.error||"Action failed");
     else window.location.reload();
   }
   function addItem(){ setItems([...items,{sku:"",description:"",quantity:1,unitPrice:"0.00",lineTotal:"0.00"}]); }

   return (
     <div className="grid">
       <div className="card">
         <h2>PO details</h2>
         {props.extractionMethod==="unreadable" && <p className="warning">This PDF could not be read automatically. Enter the details manually.</p>}
         <div className="grid">
           <label>PO number<input value={header.poNumber} onChange={e=>setHeader({...header,poNumber:e.target.value})} disabled={!props.editable} /></label>
           <label>PO date<input value={header.poDate} onChange={e=>setHeader({...header,poDate:e.target.value})} disabled={!props.editable} /></label>
           <label>Vendor<input value={header.vendorName} onChange={e=>setHeader({...header,vendorName:e.target.value})} disabled={!props.editable} /></label>
           <label>PO total (₹)<input type="number" step="0.01" value={header.documentTotal} onChange={e=>setHeader({...header,documentTotal:e.target.value})} disabled={!props.editable} /></label>
         </div>
       </div>
       <div className="card">
         <h2>Checks</h2>
         <p>Extraction: <strong>{props.extractionMethod}</strong></p>
         {items.length===0 ? <p className="warning">Line items not checked</p> : <p className={poMismatch?"error":""}>{poMismatch?"PO total does not match line totals":"PO totals match"}</p>}
         {items.length>0 && <p>Calculated total: ₹{(calculated/100).toLocaleString("en-IN",{minimumFractionDigits:2})}</p>}
       </div>
       <div className="card" style={{gridColumn:"1/-1"}}>
         <h2>Line items</h2>
         <div className="table-wrap">
           <table>
             <thead><tr><th>SKU</th><th>Description</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr></thead>
             <tbody>
               {items.map((item,index)=>(
                 <tr key={index}>
                   <td><input value={item.sku} onChange={e=>updateItem(index,"sku",e.target.value)} disabled={!props.editable} /></td>
                   <td><input value={item.description} onChange={e=>updateItem(index,"description",e.target.value)} disabled={!props.editable} /></td>
                   <td><input type="number" value={item.quantity} onChange={e=>updateItem(index,"quantity",Number(e.target.value))} disabled={!props.editable} /></td>
                   <td><input type="number" step="0.01" value={item.unitPrice} onChange={e=>updateItem(index,"unitPrice",e.target.value)} disabled={!props.editable} /></td>
                   <td><input type="number" step="0.01" value={item.lineTotal} onChange={e=>updateItem(index,"lineTotal",e.target.value)} disabled={!props.editable} /></td>
                 </tr>
               ))}
             </tbody>
           </table>
         </div>
         {props.editable && <button className="secondary" style={{marginTop:12}} type="button" onClick={addItem}>Add line</button>}
       </div>
       {error && <div className="card error" style={{gridColumn:"1/-1"}}>{error}</div>}
       <div className="card actions" style={{gridColumn:"1/-1"}}>
         {props.editable && <><button onClick={save} type="button" className="secondary">Save draft</button><button onClick={()=>action("submit")} type="button">Submit</button></>}
         {props.approverCanDecide && <><button onClick={()=>action("approve")} type="button">Approve</button><button onClick={()=>action("reject")} type="button" className="danger">Reject</button>
           <label style={{minWidth:320}}>Rejection reason<textarea value={reason} onChange={e=>setReason(e.target.value)} /></label></>}
       </div>
     </div>
   );
 }

