   const bucket = process.env.SUPABASE_BUCKET || "po-pdfs";
   const { error } = await supabase.storage.from(bucket).upload(key, buffer, {
     contentType: "application/pdf",
     upsert: false
   });
   if (error) throw new Error(`PDF upload failed: ${error.message}`);
   return key;
 }

